class Solution {
public:
    int maxProduct(string s) {
        int n = s.size();
        vector<pair<int, int>> pal;
        for (int mask = 1; mask < (1 << n); ++mask) {
            string sub = "";
            for (int i = 0; i < n; ++i) {
                if (mask & (1 << i)) sub += s[i];
            }
            string rev = sub;
            reverse(rev.begin(), rev.end());
            if (sub == rev) {
                pal.push_back({mask, (int)sub.size()});
            }
        }
        int ans = 0;
        int m = pal.size();
        for (int i = 0; i < m; ++i) {
            for (int j = i + 1; j < m; ++j) {
                if ((pal[i].first & pal[j].first) == 0) {
                    ans = max(ans, pal[i].second * pal[j].second);
                }
            }
        }
        return ans;
    }
};

class Solution {
    public int maxProduct(String s) {
        int n = s.length();
        List<int[]> pal = new ArrayList<>();
        for (int mask = 1; mask < (1 << n); mask++) {
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < n; i++) {
                if ((mask & (1 << i)) != 0) sb.append(s.charAt(i));
            }
            String str = sb.toString();
            String rev = sb.reverse().toString();
            if (str.equals(rev)) {
                pal.add(new int[]{mask, str.length()});
            }
        }
        int ans = 0;
        for (int i = 0; i < pal.size(); i++) {
            for (int j = i + 1; j < pal.size(); j++) {
                if ((pal.get(i)[0] & pal.get(j)[0]) == 0) {
                    ans = Math.max(ans, pal.get(i)[1] * pal.get(j)[1]);
                }
            }
        }
        return ans;
    }
}

var maxProduct = function(s) {
  const n = s.length;
  const pal = [];
  for (let mask = 1; mask < (1 << n); mask++) {
    let sub = '';
    for (let i = 0; i < n; i++) {
      if (mask & (1 << i)) sub += s[i];
    }
    let isPal = true;
    for (let l = 0, r = sub.length - 1; l < r; l++, r--) {
      if (sub[l] !== sub[r]) {
        isPal = false;
        break;
      }
    }
    if (isPal) pal.push([mask, sub.length]);
  }
  let ans = 0;
  for (let i = 0; i < pal.length; i++) {
    for (let j = i + 1; j < pal.length; j++) {
      if ((pal[i][0] & pal[j][0]) === 0) {
        ans = Math.max(ans, pal[i][1] * pal[j][1]);
      }
    }
  }
  return ans;
};
